/*
 * Brand mark: drawn inline as SVG from brand-geometry.js (generated by Build/Brand/ExportBrand.ps1) and animated with
 * the Web Animations API, so the animated mark has exactly the shapes of every static mark.
 * Large marks (tier 'l') weave in, pass the shuttle out of the area and back now and then, and on click.
 * Small marks (tier 's') loop a short pass while working and settle when done. Both nudge the shuttle on hover.
 * Nothing moves while the page is hidden, when reduced motion is requested, or when the editor setting Animate Mark is off.
 */
(function () {
  'use strict';

  const NS = 'http://www.w3.org/2000/svg';
  const GEOMETRY = window.ShuttlegentBrandGeometry;
  const [VIEW_X, VIEW_Y, VIEW_WIDTH, VIEW_HEIGHT] = GEOMETRY.viewBox;
  const AXIS = GEOMETRY.shuttle.axisDeg * Math.PI / 180;
  const SETTLE = 'cubic-bezier(.16,1,.3,1)';

  // Seconds between idle passes of a large mark
  const IDLE_MIN_S = 6;
  const IDLE_MAX_S = 11;

  // Motion each tier plays for a request; loops run until rested
  const MOTIONS_OF = {
    l: { intro: 'weave', idle: 'pass', click: 'pass', hover: 'nudge' },
    s: { working: 'passLoop', done: 'settle', hover: 'nudge' }
  };
  const LOOPS = new Set(['working']);

  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const marks = new Set();
  let enabled = true;

  const along = (distance) => 'translate(' + (Math.cos(AXIS) * distance).toFixed(1) + 'px,' + (Math.sin(AXIS) * distance).toFixed(1) + 'px)';
  const run = (nodes, frames, options) => [].concat(nodes).map((node) => node.animate(frames, Object.assign({ fill: 'none' }, options)));
  const wait = (ms) => new Promise((resolve) => window.setTimeout(resolve, ms));

  function element(tag, attributes) {
    const node = document.createElementNS(NS, tag);
    for (const key in attributes) node.setAttribute(key, attributes[key]);
    return node;
  }

  // A group the motions transform, pivoting on (x, y) of the view box
  function part(shape, x, y) {
    const group = element('g', {});
    group.style.transformBox = 'view-box';
    group.style.transformOrigin = (x - VIEW_X) + 'px ' + (y - VIEW_Y) + 'px';
    if (shape) group.appendChild(shape);
    return group;
  }

  function threadShape(side) {
    const t = GEOMETRY.thread;
    return element('rect', { x: side * t.centerX - t.width / 2, y: t.top, width: t.width, height: t.height, rx: t.width / 2, fill: GEOMETRY.colors.ivory });
  }

  // Red-white palette, depth order left thread, shuttle, right thread
  function build() {
    const svg = element('svg', { viewBox: GEOMETRY.viewBox.join(' '), 'aria-hidden': 'true', focusable: 'false' });
    const whole = part(null, 0, 0);
    const left = part(threadShape(-1), -GEOMETRY.thread.centerX, 0);
    const shuttle = part(element('path', { d: GEOMETRY.shuttle.d, fill: GEOMETRY.colors.red, transform: 'rotate(' + GEOMETRY.shuttle.axisDeg + ')' }), 0, 0);
    const right = part(threadShape(1), GEOMETRY.thread.centerX, 0);
    whole.append(left, shuttle, right);
    svg.appendChild(whole);
    return { svg: svg, parts: { whole: whole, left: left, shuttle: shuttle, right: right } };
  }

  /* Each motion returns its duration in ms; loops return 0 and run until rested. */
  const MOTIONS = {
    // Threads drop into place from above and below, then the shuttle slides in between them along its axis
    weave(p) {
      run(p.left, [{ transform: 'translateY(-40px)', opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 1100, easing: SETTLE, fill: 'backwards' });
      run(p.right, [{ transform: 'translateY(40px)', opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 1100, delay: 150, easing: SETTLE, fill: 'backwards' });
      run(p.shuttle, [{ transform: along(-220), opacity: 0 }, { transform: along(-60), opacity: 1, offset: .35 }, { transform: 'none', opacity: 1 }], { duration: 1300, delay: 600, easing: SETTLE, fill: 'backwards' });
      return 1900;
    },
    // Out along the axis past the upper right edge of the area, back in from the lower left on the same line
    pass(p, mark) {
      const area = mark.area.getBoundingClientRect();
      const ctm = mark.svg.getScreenCTM();
      if (!ctm || area.width === 0) return 0;
      const scale = ctm.a;
      const cx = ctm.e - area.left;
      const cy = ctm.f - area.top;
      const ux = Math.cos(AXIS);
      const uy = Math.sin(AXIS);
      const halfX = Math.hypot(GEOMETRY.shuttle.halfLength * ux, GEOMETRY.shuttle.halfThickness * uy) * scale;
      const halfY = Math.hypot(GEOMETRY.shuttle.halfLength * uy, GEOMETRY.shuttle.halfThickness * ux) * scale;
      const exitDistance = (Math.min((area.width + halfX - cx) / ux, (cy + halfY) / -uy) + 20) / scale;
      const enterDistance = (Math.min((cx + halfX) / ux, (area.height + halfY - cy) / -uy) + 20) / scale;
      const generation = mark.generation;
      (async () => {
        try {
          await p.shuttle.animate([
            { transform: 'none', easing: 'cubic-bezier(.3,0,.6,1)' },
            { transform: along(-12), offset: .3, easing: 'cubic-bezier(.6,0,.95,.4)' },
            { transform: along(exitDistance), offset: 1 }
          ], { duration: 620, fill: 'forwards' }).finished;
          await wait(200);
          if (mark.generation !== generation) return;
          p.shuttle.getAnimations().forEach((animation) => animation.cancel());
          await p.shuttle.animate([{ transform: along(-enterDistance) }, { transform: 'none' }], { duration: 640, easing: 'cubic-bezier(.05,.7,.2,1)', fill: 'forwards' }).finished;
          p.shuttle.getAnimations().forEach((animation) => animation.cancel());
          run([p.left, p.right], [{ transform: 'none' }, { transform: 'scaleY(.97)', offset: .35 }, { transform: 'none' }], { duration: 420, easing: 'ease-out' });
        } catch (error) {
          // Rested or interrupted; the mark is already back at rest
        }
      })();
      return 620 + 200 + 640 + 420;
    },
    // The shuttle gives a short push along its axis and springs back
    nudge(p) {
      run(p.shuttle, [{ transform: 'none' }, { transform: along(14), offset: .35 }, { transform: along(-4), offset: .7 }, { transform: 'none' }], { duration: 600, easing: 'ease-in-out' });
      return 600;
    },
    // The pass in small: out of the mark's own box to the upper right and back from the lower left, every 2 s
    passLoop(p) {
      run(p.shuttle, [
        { transform: 'none', easing: 'cubic-bezier(.5,0,.9,.5)' },
        { transform: along(330), offset: .2 },
        { transform: along(-330), offset: .26, easing: 'cubic-bezier(.05,.7,.2,1)' },
        { transform: 'none', offset: .5 },
        { transform: 'none' }
      ], { duration: 2000, iterations: Infinity });
      return 0;
    },
    // The shuttle comes to rest with a small overshoot and the threads give
    settle(p) {
      run(p.shuttle, [{ transform: along(-10) }, { transform: along(3), offset: .6 }, { transform: 'none' }], { duration: 520, easing: 'ease-out' });
      run([p.left, p.right], [{ transform: 'none' }, { transform: 'scaleY(.95)', offset: .5 }, { transform: 'none' }], { duration: 520, easing: 'ease-out' });
      return 520;
    }
  };

  function canAnimate() {
    return enabled && !reducedMotion.matches && !document.hidden;
  }

  function stop(mark) {
    ++mark.generation;
    window.clearTimeout(mark.endTimer);
    mark.svg.getAnimations({ subtree: true }).forEach((animation) => animation.cancel());
  }

  function start(mark) {
    stop(mark);
    const name = MOTIONS_OF[mark.tier][mark.motion];
    if (!name || !canAnimate()) {
      if (!LOOPS.has(mark.motion)) mark.motion = null;
      return;
    }
    const duration = MOTIONS[name](mark.parts, mark);
    if (LOOPS.has(mark.motion)) return;
    mark.endTimer = window.setTimeout(() => {
      mark.motion = null;
    }, duration);
  }

  function scheduleIdle(mark) {
    window.clearTimeout(mark.idleTimer);
    if (mark.tier !== 'l') return;
    const delay = (IDLE_MIN_S + Math.random() * (IDLE_MAX_S - IDLE_MIN_S)) * 1000;
    mark.idleTimer = window.setTimeout(() => {
      if (!mark.motion) play(mark, 'idle');
      scheduleIdle(mark);
    }, delay);
  }

  /** Draws the mark into an element as tier 'l' (large) or 's' (small); a large mark's pass flies to the edges of area. */
  function attach(host, tier, area) {
    const drawn = build();
    const mark = { element: host, tier: tier, area: area || document.body, svg: drawn.svg, parts: drawn.parts, motion: null, generation: 0, endTimer: 0, idleTimer: 0 };
    host.classList.add('mark', 'mark-' + tier);
    host.replaceChildren(drawn.svg);
    host.addEventListener('mouseenter', () => {
      if (!mark.motion) play(mark, 'hover');
    });
    if (tier === 'l') {
      host.addEventListener('click', () => {
        play(mark, 'click');
        scheduleIdle(mark);
      });
    }
    marks.add(mark);
    scheduleIdle(mark);
    return mark;
  }

  function detach(mark) {
    stop(mark);
    window.clearTimeout(mark.idleTimer);
    marks.delete(mark);
  }

  function play(mark, motion) {
    mark.motion = MOTIONS_OF[mark.tier][motion] ? motion : null;
    start(mark);
  }

  function rest(mark) {
    mark.motion = null;
    stop(mark);
  }

  // Stops every mark when motion is no longer allowed; resumes running loops when it is again
  function wake() {
    for (const mark of marks) {
      if (!canAnimate()) {
        stop(mark);
        if (!LOOPS.has(mark.motion)) mark.motion = null;
      } else if (LOOPS.has(mark.motion) && !mark.svg.getAnimations({ subtree: true }).length) {
        start(mark);
      }
    }
  }

  function setEnabled(value) {
    if (enabled === value) return;
    enabled = value;
    wake();
  }

  document.addEventListener('visibilitychange', wake);
  reducedMotion.addEventListener('change', wake);

  window.ShuttlegentMark = { attach: attach, detach: detach, play: play, rest: rest, setEnabled: setEnabled };
})();
